//@version=6
indicator("arrow static role omitted-directions")
plotarrow(close,title="Omitted directions")

//@version=6
indicator("arrow static role explicit-na-directions")
plotarrow(close,title="Explicit NA directions",colorup=na,colordown=na)

//@version=6
indicator("static role const alias")
const color UP=color.new(#336699,70)
const color DOWN=color.new(#993366,40)
plotarrow(close-close[1],colorup=UP,colordown=DOWN)

//@version=6
indicator("effective static var")
var color UP=color.new(#336699,70)
plotarrow(close-close[1],colorup=UP,colordown=#993366)

//@version=6
indicator("effective static dead input")
plotarrow(close-close[1],colorup=true ? color.new(#336699,70) : input.color(#669933,"Unused"),colordown=#993366)

//@version=6
indicator("persistent later write")
var color UP=color.new(#336699,70)
plotarrow(close-close[1],colorup=UP,colordown=#993366)
UP:=#669933

//@version=6
indicator("persistent same later write")
var color UP=color.new(#336699,70)
plotarrow(close-close[1],colorup=UP,colordown=#993366)
UP:=color.new(#336699,70)

//@version=6
indicator("persistent same before write")
var color UP=color.new(#336699,70)
UP:=color.new(#336699,70)
plotarrow(close-close[1],colorup=UP,colordown=#993366)

//@version=6
indicator("persistent dead later write")
var color UP=color.new(#336699,70)
plotarrow(close-close[1],colorup=UP,colordown=#993366)
if false
    UP:=#669933

//@version=6
indicator("fractional static arrow alpha")
plotarrow(close-close[1],colorup=color.new(#336699,70.25),colordown=color.new(#993366,40.125))

//@version=6
indicator("constant gradient arrow")
plotarrow(close-close[1],colorup=color.from_gradient(0.5,0,1,#336699,#993366),colordown=#993366)

//@version=6
indicator("dynamic gradient arrow")
plotarrow(close-close[1],colorup=color.from_gradient(close,0,1,#336699,#993366),colordown=#993366)

//@version=6
indicator("colorer callsite persistent pair")
var color UP=color.new(#336699,70)
plotarrow(close,title="Before",colorup=UP,colordown=#993366)
UP:=#669933
plotarrow(close,title="After",colorup=UP,colordown=#993366)

//@version=6
indicator("colorer callsite false prior")
var color UP=color.new(#336699,70)
if false
    UP:=#669933
plotarrow(close,title="After false",colorup=UP,colordown=#993366)

//@version=6
indicator("colorer callsite true prior")
var color UP=color.new(#336699,70)
if true
    UP:=#669933
plotarrow(close,title="After true",colorup=UP,colordown=#993366)

//@version=6
indicator("arrow helper source only before")
identityColor(color c)=>c
var color UP=color.new(#336699,70)
plotarrow(close,title="Only helper before",colorup=identityColor(UP),colordown=#993366)
UP:=#669933

//@version=6
indicator("arrow helper source unchanged persistent")
identityColor(color c)=>c
var color UP=color.new(#336699,70)
plotarrow(close,title="Helper unchanged persistent",colorup=identityColor(UP),colordown=#993366)

//@version=6
indicator("zero argument unchanged persistent color")
var color UP=color.new(#336699,70)
currentColor()=>UP
plotarrow(close,title="Unchanged helper",colorup=currentColor(),colordown=#993366)
